```sql
SELECT id FROM cards WHERE duelDeck = 'a';
```

```sql
SELECT CAST(SUM(CASE WHEN cardKingdomId IS NOT NULL AND cardKingdomFoilId IS NOT NULL THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM cards WHERE name = 'Coldsnap';
```

```sql
SELECT COUNT(printings) FROM cards WHERE power > 3 AND power <= 10;
```

```sql
SELECT Age FROM users WHERE Location = 'York' ORDER BY Reputation DESC LIMIT 1;
```

```sql
SELECT notes FROM income WHERE date_received = '2019-09-14' AND source = 'fundraising proceeds';
```

```sql
SELECT SEX, COUNT(ID) FROM Patient WHERE ID IN (SELECT ID FROM Laboratory) GROUP BY SEX;
```
